question:
In NextJS 12, how can I pass the raw JSON body to a Stripe webhook endpoint so `stripe.webhooks.constructEvent` succeeds? I created a test webhook in the Stripe dashboard, revealed the test webhook Signing Secret (`whsec_...`), put it in my env var, and when I trigger the test webhook I can log the Stripe signature, the signing secret, and the request body, but I constantly get:

`Error: construction of webhook event returned an error: No signatures found matching the expected signature for payload. Are you passing the raw request body you received from Stripe? https://github.com/stripe/stripe-node#webhook-signing`

I tried many solutions, including https://github.com/vercel/next.js/discussions/13405. One version of my code is:

```js
import getRawBody from "raw-body";

const stripe = require("stripe")(process.env.STRIPE_SECRET_KEY);

const webhookSecret = process.env.STRIPE_WEBHOOK_ENDPOINT_SECRET;

export const config = {
  api: {
    bodyParser: false,
  },
};

const webhookHandler = async (req, res) => {
  if (req.method === "POST") {
    const rawBody = await getRawBody(req);

    // Extract Stripe signature from header
    const signature = req.headers["stripe-signature"];
    console.log(rawBody)
    console.log(signature)
    console.log(webhookSecret)

    let event;

    // Attempt to reconstruct and validate passed event
    try {
      event = stripe.webhooks.constructEvent(rawBody, signature, webhookSecret);
    } catch (err) {
      res
        .status(400)
        .send(
          `Error: construction of webhook event returned an error: ${err.message}`,
        );
      return;
    }

    console.log("success!")

    res.json({ received: true });
  } else {

    res.setHeader("Allow", "POST");
    res.status(405).end("Method Not Allowed");

  }
};

export default webhookHandler;

```

I also tried this and got the same error:

```js
import { buffer } from 'micro';
import Cors from 'micro-cors';

const stripe = require("stripe")(process.env.STRIPE_SECRET_KEY);

const webhookSecret = process.env.STRIPE_WEBHOOK_ENDPOINT_SECRET;

// Stripe requires the raw body to construct the event.
export const config = {
  api: {
    bodyParser: false,
  },
};

const cors = Cors({
  allowMethods: ['POST', 'HEAD'],
});

const webhookHandler = async (req, res) => {
  if (req.method === 'POST') {
    const buf = await buffer(req);
    const sig = req.headers['stripe-signature'];

    let event;

    try {
      event = stripe.webhooks.constructEvent(
        buf.toString(),
        sig,
        webhookSecret
      );
    } catch (err) {
      console.log(`❌ Error message: ${err.message}`);
      res.status(400).send(`Webhook Error: ${err.message}`);
      return;
    }


    if (event.type === 'payment_intent.succeeded') {
      const paymentIntent = event.data.object;
      console.log(`💰 PaymentIntent status: ${paymentIntent.status}`);
    } else if (event.type === 'payment_intent.payment_failed') {
      const paymentIntent = event.data.object;
      console.log(
        `❌ Payment failed: ${paymentIntent.last_payment_error?.message}`
      );
    } else if (event.type === 'charge.succeeded') {
      const charge = event.data.object;
      console.log(`💵 Charge id: ${charge.id}`);
    } else {
      console.warn(`🤷‍♀️ Unhandled event type: ${event.type}`);
    }

    res.json({ received: true });
  } else {
    res.setHeader('Allow', 'POST');
    res.status(405).end('Method Not Allowed');
  }
};

export default cors(webhookHandler);
```

Please help resolve why Stripe says no signatures match the expected signature for the payload.

In ImageMagick commit/version `4b0ce67c9a20fe6d72ed59b7dc327b1042f57c4f` on Linux Ubuntu 20.04, I found code in the Magick++ demo/test utility `shapes.cpp` that reads the externally controlled `SRCDIR` environment variable with `getenv`, concatenates it into a file path, and passes it directly to the `Image` constructor. For example:

```cpp
// Method: main#7#65#shapes.cpp
int main( int , char ** argv) {
    try {
        string srcdir("");
        if(getenv("SRCDIR") != 0)
            srcdir = getenv("SRCDIR");
        Image image( "300x300", "white" );
        std::vector<Coordinate> poly_coord;
        poly_coord.push_back( Coordinate(30,30) );
        poly_coord.push_back( Coordinate(100,10) );
        poly_coord.push_back( Coordinate(190,290) );
        poly_coord.push_back( Coordinate(30,290) );
        Image texture( srcdir + "tile.miff" );
        image.fillPattern( texture );
        // Further processing...
    }
    catch( exception &error_ ) {
        cout << "Caught exception: " << error_.what() << endl;
        return 1;
    }
}
```

If I run:

```sh
export SRCDIR="../../etc/"
./shapes
```

this appears to allow path traversal / insecure file access to arbitrary files, which I classified as CWE-552. Is this a security vulnerability in ImageMagick, and how should this be mitigated?
